import { useTranslate } from "../../../../i18n/use-translate";
import type { WellnessBadgeDef } from "./wellness-badge-defs";

export type WellnessBadgeProps = {
  def: WellnessBadgeDef;
  value: string;
};

const badgeClass =
  "inline-flex items-center gap-1 rounded-lg bg-surface-elevated px-1.5 py-0.5 text-xs tabular-nums text-ink-body";

/**
 * A read-only wellness value. It used to link to a per-metric trends page;
 * those pages are no longer mounted, so the badge stays informational rather
 * than becoming a link into the calendar fallback.
 */
export function WellnessBadge({ def, value }: WellnessBadgeProps) {
  const t = useTranslate("calendar");
  return (
    <span
      aria-label={`${t(`wellnessBand.${def.metric}`)} ${value}`}
      data-testid={`wellness-badge-${def.metric}`}
      className={badgeClass}
    >
      <def.icon className="h-3 w-3 shrink-0" aria-hidden="true" />
      <span>{value}</span>
    </span>
  );
}
